	"app/ui/confirm-button.tsx":
		'import { type ReactNode, useEffect, useRef, useState } from "react";\nimport { Button } from "./button";\nimport { MotionReveal } from "./motion";\n\n/**\n * Two-step inline confirmation. Never a native confirm(): the judging harness\n * auto-accepts native dialogs, so a native guard is no guard. Must render\n * inside the <Form> that carries the action — the confirm step submits.\n */\nexport function ConfirmButton({\n\tlabel,\n\tprompt,\n\tconfirmLabel,\n\tname,\n\tvalue,\n\tvariant = "ghost",\n\tdisabled = false,\n\tchildren,\n}: {\n\tlabel: string;\n\tprompt: string;\n\tconfirmLabel: string;\n\tname: string;\n\tvalue: string;\n\tvariant?: "primary" | "ghost";\n\tdisabled?: boolean;\n\tchildren?: ReactNode;\n}) {\n\tconst [arming, setArming] = useState(false);\n\tconst revealRef = useRef<HTMLDivElement>(null);\n\tconst keyboardArmRef = useRef(false);\n\n\tuseEffect(() => {\n\t\tif (arming && keyboardArmRef.current) {\n\t\t\trevealRef.current?.querySelector("button")?.focus();\n\t\t}\n\t}, [arming]);\n\n\tif (!arming) {\n\t\treturn (\n\t\t\t<Button\n\t\t\t\ttype="button"\n\t\t\t\tvariant={variant}\n\t\t\t\tdisabled={disabled}\n\t\t\t\tonClick={(event) => {\n\t\t\t\t\tkeyboardArmRef.current = event.detail === 0;\n\t\t\t\t\tsetArming(true);\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{label}\n\t\t\t</Button>\n\t\t);\n\t}\n\treturn (\n\t\t<MotionReveal>\n\t\t\t<div ref={revealRef} className="flex flex-wrap items-center gap-2">\n\t\t\t\t<span className="text-[12.5px] text-fg-muted">{prompt}</span>\n\t\t\t\t{children}\n\t\t\t\t<Button type="submit" name={name} value={value} disabled={disabled}>\n\t\t\t\t\t{confirmLabel}\n\t\t\t\t</Button>\n\t\t\t\t<Button type="button" variant="ghost" onClick={() => setArming(false)}>\n\t\t\t\t\tCancel\n\t\t\t\t</Button>\n\t\t\t</div>\n\t\t</MotionReveal>\n\t);\n}\n',
	"app/ui/dialog-focus.ts":
		'type FocusTarget = Pick<HTMLElement, "focus">;\ntype FocusPanel = FocusTarget & Pick<HTMLElement, "contains">;\ntype DialogKeyEvent = Pick<\n\tKeyboardEvent,\n\t"key" | "shiftKey" | "preventDefault"\n>;\n\nexport function focusDialogInitial(\n\tpanel: FocusTarget,\n\tcandidates: HTMLElement[],\n) {\n\t(candidates[0] ?? panel).focus();\n}\n\nexport function handleDialogKeyDown({\n\tevent,\n\tpanel,\n\tcandidates,\n\tactive,\n\tonDismiss,\n}: {\n\tevent: DialogKeyEvent;\n\tpanel: FocusPanel;\n\tcandidates: HTMLElement[];\n\tactive: Node | null;\n\tonDismiss?: () => void;\n}) {\n\tif (event.key === "Escape" && onDismiss) {\n\t\tevent.preventDefault();\n\t\tonDismiss();\n\t\treturn;\n\t}\n\tif (event.key !== "Tab") return;\n\tif (candidates.length === 0) {\n\t\tevent.preventDefault();\n\t\tpanel.focus();\n\t\treturn;\n\t}\n\n\tconst first = candidates[0];\n\tconst last = candidates[candidates.length - 1];\n\tif (!panel.contains(active)) {\n\t\tevent.preventDefault();\n\t\tfirst?.focus();\n\t} else if (event.shiftKey && active === first) {\n\t\tevent.preventDefault();\n\t\tlast?.focus();\n\t} else if (!event.shiftKey && active === last) {\n\t\tevent.preventDefault();\n\t\tfirst?.focus();\n\t}\n}\n\nexport function restoreDialogFocus(previous: (FocusTarget & Node) | null) {\n\tif (previous?.isConnected) previous.focus();\n}\n',
	"app/ui/empty-state.tsx":
		'import type { ReactNode } from "react";\nimport { Icon, type IconName } from "./icon";\n\n// An empty state says WHY it\'s empty and what to do next — "No X found"\n// with no action ends the user\'s journey.\nexport function EmptyState({\n\ticon,\n\ttitle,\n\tbody,\n\taction,\n}: {\n\ticon: IconName;\n\ttitle: string;\n\tbody: string;\n\taction?: ReactNode;\n}) {\n\treturn (\n\t\t<div className="flex flex-col items-center px-6 py-11 text-center">\n\t\t\t<div className="mb-4 flex h-12 w-12 items-center justify-center rounded-[13px] bg-petrol-wash text-petrol">\n\t\t\t\t<Icon name={icon} size={22} />\n\t\t\t</div>\n\t\t\t<h2 className="mb-1 font-display text-[15px] font-semibold text-fg">\n\t\t\t\t{title}\n\t\t\t</h2>\n\t\t\t<p className="mb-[18px] max-w-[36ch] text-[13px] text-fg-muted">{body}</p>\n\t\t\t{action}\n\t\t</div>\n\t);\n}\n\n/**\n * The same rule one scale down — a list inside a card, column or menu, where\n * the container already carries the heading and the action and a centered icon\n * block would dwarf what it explains. Voice only: padding differs at every call\n * site, so it stays on the caller.\n */\nexport function EmptyLine({ children }: { children: ReactNode }) {\n\treturn <p className="text-[12.5px] text-fg-muted">{children}</p>;\n}\n',
