		'{\n\t"files": [],\n\t"references": [\n\t\t{ "path": "./tsconfig.node.json" },\n\t\t{ "path": "./tsconfig.cloudflare.json" }\n\t],\n\t"compilerOptions": {\n\t\t"checkJs": true,\n\t\t"verbatimModuleSyntax": true,\n\t\t"skipLibCheck": true,\n\t\t"strict": true,\n\t\t"noUncheckedIndexedAccess": true,\n\t\t// Zero violations the day these went on: a free ratchet, so dead bindings\n\t\t// fail the build instead of waiting for a reviewer to notice them.\n\t\t"noUnusedLocals": true,\n\t\t"noUnusedParameters": true,\n\t\t"noEmit": true\n\t}\n}\n',
